    /* Session 29 — the public page for LiczMat Pro (/liczmat-pro/). Short and concrete,
       and the only Pro address a visitor with no plan is meant to arrive on. Everything
       the page says about the modules and the price comes from keys that already
       existed; what is written here is the half nobody else says — what stays free, what
       Pro deliberately does not do, and the three steps from a free account to a plan. */
    propage_meta: "LiczMat Pro: klienci, zlecenia, wyceny, terminarz i historia pracy obok kalkulatorów. Co obejmuje plan Pro, ile kosztuje i czego w nim nie ma.",
    propage_h_mods: "Co obejmuje LiczMat Pro",
    propage_mods_d: "Pięć modułów. Stoją obok tego, co już liczysz — nie zastępują kalkulatorów, tylko dokładają do nich prowadzenie roboty.",
    propage_h_free: "Co masz bez Pro",
    propage_free_d: "Za to nie płacisz. Liczenie działa bez konta i tak zostanie.",
    propage_free_1: "Wszystkie kalkulatory z pełnym wynikiem i katalog materiałów.",
    propage_free_2: "Projekty, pomieszczenia i zapisane kalkulacje — w tej przeglądarce, bez rejestracji.",
    propage_free_3: "Listy materiałów i koszty projektu. Darmowe konto dokłada synchronizację z telefonem i kosztorys do udostępnienia linkiem.",
    propage_h_not: "Czego LiczMat Pro nie robi",
    propage_not_1: "To nie jest ERP ani program księgowy: bez faktur, podatków, magazynu i kadr.",
    propage_not_2: "Wycena to materiał, robocizna, koszty dodatkowe, marża i suma. Bez rabatów, numerów i dat wystawienia.",
