    propage_h_pay: "Ile kosztuje",
    propage_h_how: "Jak włączyć Pro",
    propage_how_1: "Załóż darmowe konto LiczMat — plan trzyma się konta, nie przeglądarki.",
    propage_how_2: "Wykup subskrypcję na stronie swojego konta. To jedyne miejsce, w którym LiczMat bierze pieniądze; płatność obsługuje Stripe.",
