    guide_calcs_back: "Guides that use this calculator",

    /* Guides added 2026-08-08: adhesive, skim coat, ETICS, board cutting. */
    g_klej_t: "How much tile adhesive",
    g_klej_d: "Adhesive use follows the notched trowel, and the trowel follows the tile format. Then the grout, and the tiles themselves with an off-cut allowance.",
    g_klej_s1: "Pick the trowel for the tile format: 6 mm for small wall tiles, 8–10 mm for 60×60 porcelain, 12 mm and back-buttering for large formats.",
    g_klej_s2: "Multiply the area by the bag's consumption and divide by the bag weight. Typical figures are 4 kg/m² at a 6 mm trowel and 5 kg/m² at 10 mm.",
    g_klej_s3: "Work out the grout separately: it follows the tile size, its thickness and the joint width. Count the tiles themselves with an off-cut allowance.",
    g_klej_tip: "The consumption on the bag assumes a flat substrate. A bowed wall drinks far more adhesive than the label says. Over about 5 mm out of true, level the substrate first: adhesive costs more than levelling compound.",
    g_gladz_t: "How much skim coat for a wall",
    g_gladz_d: "Skim coat is counted in kilograms per square metre per millimetre of layer. Two thin layers rather than one thick one.",
    g_gladz_s1: "Work out the wall and ceiling area and take off the windows and doors. That area is the starting point for every layer.",
    g_gladz_s2: "Take the bag's consumption: gypsum skim about 1 kg/m² per millimetre, polymer about 1.2 kg/m². Multiply by the layer thickness.",
    g_gladz_s3: "Multiply by the number of layers and divide by the bag weight. Round up — you cannot buy part of a bag.",
    g_gladz_tip: "On raw plaster the first layer goes on thicker than the label assumes, because it fills the unevenness. Count it as 1.5 mm and the second as 0.5 mm. Prime first: without primer the skim pulls water out and dusts.",
    g_ocieplenie_t: "Insulating a house with EPS",
    g_ocieplenie_d: "An ETICS system is not just the foam: it is the adhesive, the dowels, the mesh, the reinforcing layer and the render. Every one of them comes off the same area.",
    g_ocieplenie_s1: "Work out the facade area: the building's perimeter times its height, less windows and doors. Count the reveals separately if you are insulating them.",
    g_ocieplenie_s2: "Choose the foam thickness and count the bundles. Then the dowels: typically 6 per m², more at corners and above 8 m. Count the adhesive twice, once for bonding and once for the reinforcing layer.",
    g_ocieplenie_s3: "Allow about 10 % on the mesh for overlaps, and take the thin-coat render from its own consumption per m².",
    g_ocieplenie_tip: "The dowel count is not one number for the whole house. The corner zone needs them denser than the middle of a wall, and above 8 m the building moves into a higher wind zone. Check the design or the system's guidance before ordering.",
    g_rozkroj_t: "Cutting a furniture board with less waste",
    g_rozkroj_d: "How many boards to buy for a list of parts, and how to lay them out so the off-cut is as small as possible. The saw's kerf takes material too.",
    g_rozkroj_s1: "List the parts: width, length and quantity. Add an allowance for edging if the edge band goes on after cutting.",
    g_rozkroj_s2: "Give the board format and the saw kerf. A panel saw takes about 3–4 mm on every cut; over a few dozen cuts that is whole centimetres.",
    g_rozkroj_s3: "Decide whether parts may be rotated. A board with a grain or a pattern cannot be, and the waste grows — calculate both and compare.",
    g_rozkroj_tip: "The result is a cutting plan, not an order. Before you order, check that every part fits the way the algorithm turned it. With a grain, rotating a part changes how the front looks even when the size is right.",

    /* /aplikacja/ — the one page where the Android app is the subject. */
