    note_waste: "Запасу 5–7% вистачає при прямому розкладі. Великий формат, діагональ або розклад у цеглу потребують 10–15%. Купуй з однієї партії.",
    note_wallpaper: "У шпалер із рапортом кожна смуга подовжується до цілої кратності рапорту, тож із рулону виходить менше смуг. Рапорт 0 означає шпалери без візерунка для підгонки.",
    note_linear: "Пропил відраховується на кожному наступному різі в хлисті, не на першому. Алгоритм first-fit decreasing дає добрий, але не завжди оптимальний розкрій.",
    note_sheet: "Гільйотинний розкрій: кожен різ проходить крізь усю плиту, як на форматно-розкрійному верстаті. Вимкни поворот, коли плита має текстуру чи спрямований малюнок.",
    note_concrete: "Перерахунок припускає мішок 25 кг сухої суміші, що дає близько 12,5 л бетону. Перевір вихід на мішку, він різниться між виробниками.",
    note_mortar: "Витрата клею залежить від зубця шпателя і рівності основи. Наведене значення — з технічної карти; на кривій стіні воно може зрости наполовину.",
    note_screed: "Перерахунок припускає густину близько 2,0 кг на літр розчину. Ангідритні та легкі стяжки мають іншу густину — перевір мішок.",
    note_grout: "Витрата затирки росте з шириною шва і товщиною плитки, а падає з форматом. При великому керамограніті на тонкому шві виходить дуже мало.",
    note_masonry: "Кількість штук на м² походить із розміру блока разом зі швом. Запас 5% покриває підрізку та бій у транспорті.",
    note_insulation: "Кількість дюбелів залежить від висоти будівлі та вітрової зони — 6 шт./м² типово для першого і другого поверху. Сітку рахуй із перекриттям 10%.",
    note_studwall: "Крок 60 см — стандарт під лист 1,2 м. Під важче облицювання або плитку зменш до 40 см. Листи рахуй на обидва боки.",
