    g_malowanie_d: "Plocha stien a stropu, odčítané otvory, prepočet na celé balenia s rezervou na druhý náter.",
    g_malowanie_s1: "Odmeraj izbu: dĺžku, šírku a výšku. Obvod krát výška dá plochu stien, dĺžka krát šírka strop.",
    g_malowanie_s2: "Odčítaj okná a dvere. Typické okno má asi 1,5 m², typické dvere asi 1,8 m².",
    g_malowanie_s3: "Vydeľ výdatnosťou uvedenou na obale a vynásob počtom náterov. Zaokrúhli nahor na celé balenia.",
    g_malowanie_tip: "Výdatnosť na etikete platí pre hladký, napenetrovaný podklad. Savá omietka spotrebuje viac, takže počítaj s rezervou alebo najprv napenetruj.",
    g_plytki_t: "Koľko obkladov a lepidla do kúpeľne",
    g_plytki_d: "Podlaha a steny v metroch štvorcových, rezerva na prírez, lepidlo a škárovacia hmota prepočítané na vrecia.",
    g_plytki_s1: "Počítaj podlahu a steny zvlášť. Pri stenách vezmi obvod krát výšku obkladu a odčítaj dvere a okno.",
    g_plytki_s2: "Pridaj rezervu na prírez: 5–7% pri rovnej väzbe, 10–15% pri veľkom formáte alebo diagonálnej väzbe.",
    g_plytki_s3: "Lepidlo spočítaj z výdatnosti pre zvolené zubové hladidlo, škárovaciu hmotu z rozmeru dlaždice a šírky škáry.",
    g_plytki_tip: "Kupuj obklady z jednej výrobnej šarže. Šarže sa líšia odtieňom aj kalibrom a o mesiac už tá istá v obchode nebude.",
    g_panele_t: "Koľko panelov na podlahu",
    g_panele_d: "Plocha podlahy, rezerva na prírez a prepočet na celé balenia.",
    g_panele_s1: "Odmeraj podlahu: dĺžka krát šírka. Výklenky a arkiere odmeraj zvlášť a pripočítaj.",
    g_panele_s2: "Pridaj rezervu na prírez: 5% pri rovnom kladení pozdĺž dlhšej steny, 10% pri diagonálnom kladení.",
    g_panele_s3: "Vydeľ plochou balenia uvedenou na obale a zaokrúhli nahor na celé balenia.",
    g_panele_tip: "Nechaj si jedno celé balenie do rezervy. Poškodenú dosku vymeníš len vtedy, ak máš presne rovnaký dekor.",
    g_sciana_t: "SDK priečka: profily a dosky",
    g_sciana_d: "Koľko profilov CW a UW, koľko sadrokartónových dosiek a koľko vaty na priečku daných rozmerov.",
    g_sciana_s1: "Zadaj šírku a výšku priečky a rozstup profilov — najčastejšie 60 cm, pod ťažším obkladom 40 cm.",
    g_sciana_s2: "Profily CW vychádzajú z rozstupu, profily UW sú podlaha a strop, teda dvojnásobok dĺžky steny.",
    g_sciana_s3: "Dosky počítaj na obe strany priečky s rezervou 10% na prírez. Vatu počítaj na plochu steny.",
    g_sciana_tip: "Dosky klaď prestriedané, aby škáry na jednej strane nevyšli na to isté miesto ako na druhej. Stena je tuhšia a škáry menej praskajú.",
    storespage_title: "Stavebniny vo tvojom okolí",
    storespage_lead: "Nájdi hobbymarket, veľkoobchod alebo stavebniny podľa polohy alebo názvu. Zoznam miest berieme z OpenStreetMap, mapu a navigáciu zabezpečuje Google Maps.",
    storespage_meta: "Nájdi stavebniny v okolí: hobbymarkety, veľkoobchody a stavebniny na mape, s trasou k vybranému miestu.",
    note_coverage: "Výdatnosť na etikete (m²/l alebo m²/balenie) platí pre hladký, napenetrovaný podklad. Savá omietka spotrebuje viac. Otvory odčítaj len vtedy, keď ich nemaľuješ.",
    note_waste: "Rezerva 5–7% stačí pri rovnej väzbe. Veľký formát, diagonálna alebo väzba na tehlu potrebujú 10–15%. Kupuj z jednej šarže.",
    note_wallpaper: "Pri tapete s raportom sa každý pás predĺži na celý násobok raportu, takže z rolky vyjde menej pásov. Raport 0 znamená tapetu bez vzoru na napojenie.",
    note_linear: "Prírez píly sa odčítava pri každom ďalšom reze v tyči, nie pri prvom. Algoritmus first-fit decreasing dá dobrý, ale nie vždy optimálny rez.",
    note_sheet: "Gilotínový rez: každý rez ide cez celú dosku, ako na formátovacej píle. Otáčanie vypni, keď má doska kresbu alebo smerový dekor.",
    note_concrete: "Prepočet predpokladá vrece 25 kg suchej zmesi, ktoré dá asi 12,5 l betónu. Skontroluj výdatnosť na vreci, líši sa podľa výrobcu.",
    note_mortar: "Spotreba lepidla závisí od zuba hladidla a rovinnosti podkladu. Uvedená hodnota je z technického listu; na krivej stene môže vzrásť o polovicu.",
    note_screed: "Prepočet predpokladá hustotu asi 2,0 kg na liter malty. Anhydritové a ľahčené potery majú inú hustotu — skontroluj vrece.",
    note_grout: "Spotreba škárovacej hmoty rastie so šírkou škáry a hrúbkou dlaždice a klesá s formátom. Pri veľkej dlažbe na úzkej škáre vyjde veľmi málo.",
    note_masonry: "Počet kusov na m² vychádza z rozmeru tvárnice vrátane škáry. Rezerva 5% pokryje prírez a praskliny pri doprave.",
    note_insulation: "Počet hmoždiniek závisí od výšky budovy a veternej oblasti — 6 ks/m² je typické pre prízemie a prvé poschodie. Sieťku počítaj s presahom 10%.",
    note_studwall: "Rozstup 60 cm je štandard pod dosku 1,2 m. Pod ťažší obklad alebo dlažbu choď na 40 cm. Dosky počítaj na obe strany.",
    note_ceiling: "Rozstup nosných CD 40 cm a závesov 90 cm je typický podhľad pod jednu dosku. Pri vyššom zaťažení treba rozstupy zhustiť.",
    note_drylining: "Metóda na lepiace terče funguje len na rovnom, nosnom podklade. Väčšie nerovnosti vyžadujú rošt.",
    note_sheathing: "Výsledok je počet celých dosiek bez plánu rezu. Ak chceš vedieť, ako ich rozrezať, použi kalkulačku rezu dosiek 2D.",
