    /* Session 29 — /liczmat-pro/, the public page for LiczMat Pro. */
    propage_meta: "LiczMat Pro: klijenti, nalozi, ponude, rokovi i povijest posla uz kalkulatore. Što pretplata Pro obuhvaća, koliko košta i čega u njoj nema.",
    propage_h_mods: "Što obuhvaća LiczMat Pro",
