    guides_lead: "Kratka uputstva: od dimenzija prostorije do spiska za kupovinu. Svaki korak vodi do odgovarajućeg kalkulatora.",
    guides_meta: "Vodiči LiczMat: koliko boje za sobu, koliko pločica i lepka za kupatilo, koliko panela za pod, koliko profila i ploča za GK pregradu.",
