    g_malowanie_t: "Koliko boje za sobu",
    g_malowanie_d: "Površina zidova i plafona, oduzeti otvori, preračunato u cele kante s rezervom za drugi sloj.",
    g_malowanie_s1: "Izmeri sobu: dužinu, širinu i visinu. Obim puta visina daje površinu zidova, dužina puta širina plafon.",
    g_malowanie_s2: "Oduzmi prozore i vrata. Tipičan prozor ima oko 1,5 m², tipična vrata oko 1,8 m².",
    g_malowanie_s3: "Podeli izdašnošću s etikete i pomnoži brojem slojeva. Zaokruži naviše na cele kante.",
    g_malowanie_tip: "Izdašnost s etikete važi za glatku, impregniranu podlogu. Upojni malter troši više, pa računaj s rezervom ili prvo impregniraj.",
    g_plytki_t: "Koliko pločica i lepka za kupatilo",
    g_plytki_d: "Pod i zidovi u kvadratnim metrima, rezerva za sečenje, lepak i fug masa preračunati u džakove.",
    g_plytki_s1: "Računaj pod i zidove odvojeno. Za zidove uzmi obim puta visinu obloge, pa oduzmi vrata i prozor.",
    g_plytki_s2: "Dodaj rezervu za sečenje: 5–7% kod ravnog slaganja, 10–15% kod velikog formata ili dijagonale.",
    g_plytki_s3: "Lepak računaj iz potrošnje za izabranu nazubljenu gletericu, fug masu iz dimenzije pločice i širine fuge.",
    g_plytki_tip: "Kupuj pločice iz jedne proizvodne serije. Serije se razlikuju u nijansi i kalibru, a za mesec dana te serije više neće biti u prodavnici.",
    g_panele_t: "Koliko panela za pod",
    g_panele_d: "Površina poda, rezerva za sečenje i preračun u cela pakovanja.",
    g_panele_s1: "Izmeri pod: dužina puta širina. Niše i erkere izmeri odvojeno i dodaj.",
    g_panele_s2: "Dodaj rezervu za sečenje: 5% kod ravnog polaganja uz duži zid, 10% kod dijagonalnog polaganja.",
    g_panele_s3: "Podeli površinom pakovanja s ambalaže i zaokruži naviše na cela pakovanja.",
    g_panele_tip: "Ostavi jedno celo pakovanje u rezervi. Oštećenu dasku menjaš samo ako imaš tačno isti dekor.",
    g_sciana_t: "GK pregrada: profili i ploče",
    g_sciana_d: "Koliko CW i UW profila, koliko gips-kartonskih ploča i koliko vune za pregradu zadatih dimenzija.",
    g_sciana_s1: "Unesi širinu i visinu pregrade i razmak profila — najčešće 60 cm, pod težom oblogom 40 cm.",
    g_sciana_s2: "CW profili proizlaze iz razmaka, UW profili su pod i plafon, dakle dvostruka dužina zida.",
    g_sciana_s3: "Ploče računaj za obe strane pregrade, s rezervom 10% za sečenje. Vunu računaj na površinu zida.",
    g_sciana_tip: "Ploče postavljaj s pomakom da spojevi na jednoj strani ne padnu na isto mesto kao na drugoj. Zid je krući, a fuge manje pucaju.",
    storespage_title: "Građevinske prodavnice u blizini",
    storespage_lead: "Nađi građevinski market, veleprodaju ili stovarište po lokaciji ili nazivu. Spisak mesta dolazi iz OpenStreetMapa, mapu i navigaciju daje Google Maps.",
    storespage_meta: "Nađi građevinsku prodavnicu u blizini: marketi, veleprodaje i stovarišta na mapi, s rutom do izabranog mesta.",
    note_coverage: "Izdašnost s etikete (m²/l ili m²/pakovanje) važi za glatku, impregniranu podlogu. Upojni malter troši više. Otvore oduzimaj samo ako ih ne farbaš.",
    note_waste: "Rezerva 5–7% dovoljna je kod ravnog slaganja. Veliki format, dijagonala ili slaganje u ciglu traže 10–15%. Kupuj iz jedne serije.",
    note_wallpaper: "Kod tapete s raportom svaka traka se produžava na ceo umnožak raporta, pa iz rolne izlazi manje traka. Raport 0 znači tapetu bez šare za spajanje.",
    note_linear: "Rez testere se oduzima kod svakog sledećeg reza u šipki, ne kod prvog. Algoritam first-fit decreasing daje dobar, ali ne uvek optimalan raspored.",
    note_sheet: "Giljotinsko sečenje: svaki rez ide kroz celu ploču, kao na formatnoj testeri. Isključi rotaciju kad ploča ima teksturu ili usmerenu šaru.",
    note_concrete: "Preračun pretpostavlja džak od 25 kg suve mešavine koji daje oko 12,5 l betona. Proveri izdašnost na džaku, razlikuje se među proizvođačima.",
    note_mortar: "Potrošnja lepka zavisi od zuba glaterice i ravnosti podloge. Navedena vrednost je iz tehničkog lista; na krivom zidu može porasti za polovinu.",
    note_screed: "Preračun pretpostavlja gustinu oko 2,0 kg po litru maltera. Anhidritni i laki estrisi imaju drugu gustinu — proveri džak.",
    note_grout: "Potrošnja fug mase raste sa širinom fuge i debljinom pločice, a pada s formatom. Kod velikog gresa na uskoj fugi ispada vrlo malo.",
    note_masonry: "Broj komada po m² proizlazi iz dimenzije bloka zajedno s fugom. Rezerva od 5% pokriva sečenje i lomove u transportu.",
    note_insulation: "Broj tiplova zavisi od visine zgrade i vetrovne zone — 6 kom/m² je tipično za prizemlje i prvi sprat. Mrežicu računaj s preklopom 10%.",
    note_studwall: "Razmak 60 cm je standard pod ploču od 1,2 m. Pod težu oblogu ili pločice spusti na 40 cm. Ploče računaj za obe strane.",
    note_ceiling: "Razmak nosećih CD 40 cm i vešalica 90 cm je tipičan plafon pod jednu ploču. Kod većeg opterećenja razmake treba zgusnuti.",
    note_drylining: "Metoda na lepak u tačkama radi samo na ravnoj, nosivoj podlozi. Veća odstupanja traže potkonstrukciju.",
    note_sheathing: "Rezultat je broj celih ploča bez plana sečenja. Ako želiš da znaš kako da ih isečeš, upotrebi kalkulator sečenja ploča 2D.",
