    g_panele_s2: "Aggiungi una scorta per i tagli: 5% posando dritto lungo la parete più lunga, 10% posando in diagonale.",
    g_panele_s3: "Dividi per la resa della confezione scritta sull'imballo e arrotonda per eccesso a confezioni intere.",
    g_panele_tip: "Tieni una confezione intera di scorta. Una doga rovinata si sostituisce solo se hai lo stesso identico decoro.",
    g_sciana_t: "Parete in cartongesso: profili e lastre",
    g_sciana_d: "Quanti profili CW e UW, quante lastre di cartongesso e quanta lana minerale per una parete di una certa misura.",
    g_sciana_s1: "Inserisci larghezza e altezza della parete e l'interasse dei montanti: di solito 60 cm, o 40 cm sotto una finitura più pesante.",
    g_sciana_s2: "I montanti CW derivano dall'interasse; le guide UW sono il pavimento e il soffitto, quindi il doppio della lunghezza della parete.",
    g_sciana_s3: "Conta le lastre per entrambe le facce della parete con una scorta del 10% per i tagli. La lana si conta sulla superficie della parete.",
    g_sciana_tip: "Sfalsa le lastre in modo che le giunzioni di una faccia non coincidano con quelle dell'altra. La parete è più rigida e le fughe si crepano meno.",
    storespage_title: "Negozi di materiali edili vicino a te",
    storespage_lead: "Trova un fai da te, un grossista o un deposito edile per posizione o per nome. L'elenco dei luoghi arriva da OpenStreetMap, la mappa e il percorso da Google Maps.",
    storespage_meta: "Trova un negozio di materiali edili vicino a te: fai da te, grossisti e depositi sulla mappa, con il percorso fino a quello che scegli.",
    note_coverage: "La resa in etichetta (m²/l o m²/confezione) presuppone una superficie liscia e trattata con primer. Un intonaco assorbente consuma di più. Sottrai le aperture solo se non le dipingi.",
    note_waste: "Una scorta del 5–7% basta per una posa dritta. Grande formato, posa diagonale o a correre richiedono il 10–15%. Compra da un solo lotto.",
    note_wallpaper: "Con un rapporto del disegno ogni telo viene allungato a un multiplo intero del rapporto, quindi da un rotolo escono meno teli. Un rapporto di 0 indica una carta senza disegno da far combaciare.",
    note_linear: "Lo spessore di taglio si sottrae a ogni taglio dopo il primo nella barra, non al primo. Il first-fit decrescente dà un buon piano di taglio, non sempre quello ottimale.",
    note_sheet: "Taglio a ghigliottina: ogni taglio attraversa tutta la lastra, come lavora una sezionatrice. Disattiva la rotazione quando la lastra ha una venatura o un disegno direzionale.",
    note_concrete: "La conversione presuppone un sacco da 25 kg di premiscelato con una resa di circa 12,5 l di calcestruzzo. Controlla la resa sul sacco: cambia da un produttore all'altro.",
    note_mortar: "Il consumo di colla dipende dalla dentatura della spatola e dalla planarità del fondo. Il valore qui è quello di scheda tecnica; su una parete storta può crescere della metà.",
    note_screed: "La conversione presuppone una densità di circa 2,0 kg per litro di malta. I massetti anidritici e quelli alleggeriti hanno una densità diversa: controlla il sacco.",
    note_grout: "Il consumo di stucco cresce con la larghezza della fuga e lo spessore della piastrella e cala con il formato. Un grande gres con fuga sottile ne richiede pochissimo.",
    note_masonry: "I pezzi per m² derivano dalla misura del blocco compresa la fuga. Una scorta del 5% copre i tagli e le rotture in trasporto.",
    note_insulation: "Il numero di tasselli dipende dall'altezza dell'edificio e dalla zona di vento: 6 per m² è tipico per il piano terra e il primo piano. Conta la rete con una sovrapposizione del 10%.",
    note_studwall: "L'interasse di 60 cm è lo standard sotto una lastra da 1,2 m. Scendi a 40 cm sotto una finitura più pesante o sotto le piastrelle. Le lastre si contano per entrambe le facce.",
    note_ceiling: "Interasse CD di 40 cm e pendini ogni 90 cm sono un controsoffitto tipico con una lastra sola. Carichi maggiori richiedono interassi più stretti.",
    note_drylining: "Il metodo a punti di colla funziona solo su un fondo piano e solido. Scarti maggiori richiedono una struttura metallica.",
    note_sheathing: "Il risultato è un conteggio di lastre intere senza piano di taglio. Se ti serve sapere come tagliarle, usa il calcolatore di taglio pannelli 2D.",
