    guides_lead: "Korte instructies: van de maten van de kamer tot een boodschappenlijst. Elke stap linkt naar de rekenmachine die het rekenwerk doet.",
    guides_meta: "LiczMat-gidsen: hoeveel verf voor een kamer, hoeveel tegels en hoeveel lijm voor een badkamer. Hoeveel vloerpanelen, hoeveel profielen voor een gipswand.",
    guide_steps_t: "Stap voor stap",
