    guide_tip_t: "Tip",
    guide_all: "Alle gidsen",
    g_malowanie_t: "Hoeveel verf voor een kamer",
    g_malowanie_d: "Het oppervlak van wanden en plafond, openingen eraf, omgerekend naar hele blikken met een marge voor de tweede laag.",
    g_malowanie_s1: "Meet de kamer: lengte, breedte en hoogte. Omtrek maal hoogte geeft het wandoppervlak, lengte maal breedte het plafond.",
    g_malowanie_s2: "Trek ramen en deuren eraf. Een gewoon raam is ongeveer 1,5 m², een gewone deur ongeveer 1,8 m².",
    g_malowanie_s3: "Deel door het rendement op het blik en vermenigvuldig met het aantal lagen. Rond af naar hele blikken.",
    g_malowanie_tip: "Het rendement op het etiket gaat uit van een glad, voorgestreken oppervlak. Zuigende pleister drinkt meer verf, dus reken extra of strijk eerst voor.",
    g_plytki_t: "Tegels en lijm voor de badkamer",
    g_plytki_d: "Vloer en wanden in vierkante meters, een marge voor snijverlies, lijm en voegmiddel omgerekend naar zakken.",
    g_plytki_s1: "Meet de vloer en de wanden apart. Neem voor de wanden de omtrek maal de betegelde hoogte en trek er de deur en het raam af.",
    g_plytki_s2: "Tel een marge voor snijverlies op: 5–7% bij recht leggen, 10–15% bij groot formaat of diagonaal.",
    g_plytki_s3: "Reken de lijm uit het verbruik voor jouw lijmkam en het voegmiddel uit de tegelmaat en de voegbreedte.",
    g_plytki_tip: "Koop tegels uit één productiepartij. Partijen verschillen in tint en maatvoering, en een maand later is die partij uit de winkel.",
    g_panele_t: "Hoeveel vloerpanelen",
    g_panele_d: "Vloeroppervlak, een marge voor snijverlies en de omrekening naar hele pakken.",
    g_panele_s1: "Meet de vloer: lengte maal breedte. Meet nissen en erkers apart en tel ze erbij op.",
    g_panele_s2: "Tel een marge voor snijverlies op: 5% bij recht leggen langs de langste wand, 10% bij diagonaal leggen.",
    g_panele_s3: "Deel door het pakrendement op de verpakking en rond af naar hele pakken.",
    g_panele_tip: "Houd één heel pak over. Een beschadigde plank ruil je alleen als je precies hetzelfde decor hebt.",
    g_sciana_t: "Gipswand: profielen en platen",
    g_sciana_d: "Hoeveel CW- en UW-profielen, hoeveel gipsplaten en hoeveel minerale wol voor een wand van een bepaalde maat.",
    g_sciana_s1: "Vul de breedte en hoogte van de wand in en de hart-op-hartafstand — meestal 60 cm, of 40 cm onder een zwaardere afwerking.",
    g_sciana_s2: "De CW-stijlen volgen uit de afstand; de UW-profielen zijn de vloer en het plafond, dus twee keer de lengte van de wand.",
    g_sciana_s3: "Tel platen voor beide zijden van de wand met 10% marge voor snijverlies. Wol wordt over het wandoppervlak geteld.",
    g_sciana_tip: "Verspring de platen zodat de naden aan de ene kant niet samenvallen met die aan de andere. De wand is stijver en de naden scheuren minder.",
    storespage_title: "Bouwmarkten bij jou in de buurt",
    storespage_lead: "Vind een doe-het-zelfzaak, groothandel of bouwdepot op locatie of op naam. De lijst met plaatsen komt van OpenStreetMap, de kaart en de route van Google Maps.",
    storespage_meta: "Vind een bouwmarkt bij jou in de buurt: doe-het-zelfzaken, groothandels en depots op een kaart, met de route naar de zaak die je kiest.",
    note_coverage: "Het rendement op het etiket (m²/l of m²/verpakking) gaat uit van een glad, voorgestreken oppervlak. Zuigende pleister gebruikt meer. Trek openingen alleen af als je ze echt niet schildert.",
    note_waste: "Een marge van 5–7% is genoeg bij recht leggen. Groot formaat, diagonaal of halfsteens vraagt 10–15%. Koop uit één partij.",
    note_wallpaper: "Bij een rapport wordt elke baan verlengd tot een heel veelvoud van het rapport, dus levert een rol minder banen op. Een rapport van 0 betekent behang zonder patroon dat moet aansluiten.",
    note_linear: "De zaagsnede gaat er bij elke snede na de eerste in een stang af, niet bij de eerste. First-fit decreasing geeft een goed, maar niet altijd optimaal zaagplan.",
    note_sheet: "Guillotinezagen: elke snede loopt over de hele plaat, zoals een plaatzaag werkt. Zet draaien uit als de plaat een nerf of een gericht patroon heeft.",
    note_concrete: "De omrekening gaat uit van een zak van 25 kg droge mix met een rendement van ongeveer 12,5 l beton. Controleer het rendement op de zak — dat verschilt per fabrikant.",
    note_mortar: "Het lijmverbruik hangt af van de lijmkam en van hoe vlak de ondergrond is. Het getal hier komt van het technische blad; op een bolle wand kan het de helft hoger liggen.",
    note_screed: "De omrekening gaat uit van een dichtheid van ongeveer 2,0 kg per liter mortel. Anhydrietvloeren en lichte dekvloeren hebben een andere dichtheid — controleer de zak.",
    note_grout: "Het voegverbruik stijgt met de voegbreedte en de tegeldikte en daalt met de tegelmaat. Grote keramiek met een smalle voeg vraagt heel weinig.",
    note_masonry: "Het aantal stuks per m² volgt uit de blokmaat inclusief de voeg. Een marge van 5% dekt snijverlies en breuk tijdens transport.",
    note_insulation: "Het aantal pluggen hangt af van de bouwhoogte en de windzone — 6 per m² is gebruikelijk voor de begane grond en de eerste verdieping. Reken het gaas met 10% overlap.",
    note_studwall: "60 cm hart-op-hart is standaard onder een plaat van 1,2 m. Ga naar 40 cm onder een zwaardere afwerking of onder tegels. Platen worden voor beide zijden geteld.",
    note_ceiling: "40 cm tussen de CD-profielen en 90 cm tussen de hangers is een gebruikelijk plafond met één plaat. Zwaardere belasting vraagt kleinere afstanden.",
    note_drylining: "De methode met lijmkoeken werkt alleen op een vlakke, stevige ondergrond. Grotere afwijkingen vragen een metalen frame.",
    note_sheathing: "Het resultaat is een aantal hele platen zonder zaagplan. Wil je weten hoe je ze zaagt, gebruik dan de rekenmachine voor 2D-zagen.",
