    ck_p_signed_in: "Het accountniveau (LiczMat of LiczMat Pro) dat bij het inloggen is onthouden. De rekenmachines laden geen Firebase en moeten toch weten of ze je een account moeten aanbieden. Er staat geen e-mailadres in en verder niets over jou.",
