    ck_p_recent: "Welke rekenmachines het laatst zijn gebruikt, zodat het overzicht ze kan tonen. Alleen de naam van het gereedschap en een datum — geen invoer en geen resultaten.",
    ck_p_ga: "Google Analytics: anoniem, samengevoegd siteverkeer. Wordt pas geschreven nadat je akkoord gaat.",
    ck_p_firebase: "De inlogsessie onder „Mijn account” en een lokale kopie van de accountgegevens. Alleen na het inloggen.",
    ck_p_maps: "De Google-kaart op de winkelpagina zet bij het laden eigen bestanden van Google neer.",
    guide_calcs_back: "Gidsen die deze rekenmachine gebruiken",
    g_klej_t: "Hoeveel tegellijm",
    g_klej_d: "Het lijmverbruik volgt de lijmkam en de lijmkam volgt het tegelformaat. Daarna het voegmiddel, en de tegels zelf met een marge voor snijverlies.",
    g_klej_s1: "Kies de kam bij het tegelformaat: 6 mm voor kleine wandtegels, 8–10 mm voor keramiek 60×60, 12 mm en dubbel lijmen bij grote formaten.",
    g_klej_s2: "Vermenigvuldig het oppervlak met het verbruik van de zak en deel door het zakgewicht. Gebruikelijk is 4 kg/m² bij een kam van 6 mm en 5 kg/m² bij 10 mm.",
    g_klej_s3: "Reken het voegmiddel apart uit: dat volgt uit de tegelmaat, de dikte en de voegbreedte. Tel de tegels zelf met een marge voor snijverlies.",
    g_klej_tip: "Het verbruik op de zak gaat uit van een vlakke ondergrond. Een bolle wand drinkt veel meer lijm dan het etiket zegt. Boven ongeveer 5 mm afwijking eerst egaliseren: lijm kost meer dan egalisatiemortel.",
    g_gladz_t: "Hoeveel plamuur voor een muur",
    g_gladz_d: "Plamuur wordt geteld in kilogram per vierkante meter per millimeter laag. Twee dunne lagen in plaats van één dikke.",
    g_gladz_s1: "Reken het oppervlak van wanden en plafond uit en haal de ramen en deuren eraf. Dat oppervlak is het beginpunt voor elke laag.",
    g_gladz_s2: "Neem het verbruik van de zak: gipsplamuur ongeveer 1 kg/m² per millimeter, polymeer ongeveer 1,2 kg/m². Vermenigvuldig met de laagdikte.",
    g_gladz_s3: "Vermenigvuldig met het aantal lagen en deel door het zakgewicht. Rond naar boven af — een halve zak koop je niet.",
    g_gladz_tip: "Op ruwe pleister gaat de eerste laag dikker op dan het etiket aanneemt, want die vult de oneffenheden. Reken hem als 1,5 mm en de tweede als 0,5 mm. Strijk eerst voor: zonder voorstrijk trekt de plamuur water weg en stuift.",
    g_ocieplenie_t: "Een huis isoleren met EPS",
    g_ocieplenie_d: "Een ETICS-systeem is niet alleen het schuim: het is de lijm, de pluggen, het gaas, de wapeningslaag en de sierpleister. Alles uit hetzelfde oppervlak.",
    g_ocieplenie_s1: "Reken het geveloppervlak uit: de omtrek van het gebouw maal de hoogte, min ramen en deuren. Tel de neggen apart als je die ook isoleert.",
    g_ocieplenie_s2: "Kies de dikte van het schuim en tel de pakken. Dan de pluggen: gebruikelijk 6 per m², meer op hoeken en boven 8 m. Tel de lijm twee keer, één keer voor het verlijmen en één keer voor de wapeningslaag.",
    g_ocieplenie_s3: "Reken ongeveer 10 % extra gaas voor de overlappen en neem de sierpleister uit het eigen verbruik per m².",
    g_ocieplenie_tip: "Het aantal pluggen geldt niet voor het hele huis. Op hoeken staan ze dichter, en boven 8 m verandert de windzone. Kijk vóór het bestellen in het ontwerp.",
    g_rozkroj_t: "Een meubelplaat zagen met minder afval",
    g_rozkroj_d: "Hoeveel platen je koopt voor een lijst met onderdelen en hoe je ze indeelt zodat het restafval zo klein mogelijk is. De zaag neemt ook materiaal weg.",
    g_rozkroj_s1: "Noteer de onderdelen: breedte, lengte en aantal. Tel een marge op voor de kantenband als die na het zagen komt.",
    g_rozkroj_s2: "Geef het plaatformaat en de zaagsnede op. Een plaatzaag neemt ongeveer 3–4 mm per snede; over enkele tientallen sneden zijn dat hele centimeters.",
    g_rozkroj_s3: "Bepaal of onderdelen mogen draaien. Een plaat met nerf of patroon mag dat niet en het afval groeit — reken beide uit en vergelijk.",
    g_rozkroj_tip: "Het resultaat is een zaagplan, geen bestelling. Kijk vóór het bestellen of elk onderdeel past zoals het algoritme het heeft gedraaid. Met een nerf verandert draaien het aanzicht ook als de maat klopt.",
    nav_app_page: "De app",
    apppage_title: "LiczMat voor Android",
    apppage_lead: "Hetzelfde rekenwerk als op de site, in je zak en zonder bereik. Rekenmachines, de materiaalcatalogus, ruimtes, projecten, een raming in PDF, een eenhedenomrekening en een kaart met bouwmaterialenhandels.",
    apppage_meta: "LiczMat voor Android: een gratis rekenmachine voor bouwmateriaal. Catalogus, ruimtes, projecten, ramingen in PDF en een winkelkaart. Rekent offline.",
