    ck_p_lang: "El idioma que elegiste en el selector, para que la siguiente visita empiece ya en él.",
    ck_p_currency: "La moneda en la que se cuentan tus precios. Se elige aparte del idioma.",
    ck_p_theme: "Claro u oscuro, si lo ajustas a mano en lugar de dejárselo al sistema.",
    ck_p_signed_in: "El nivel de la cuenta (LiczMat o LiczMat Pro) recordado al iniciar sesión. Las calculadoras no cargan Firebase y aun así tienen que saber si ofrecerte una cuenta. No contiene ningún correo ni nada más sobre ti.",
