    ck_p_signed_in: "Le niveau du compte (LiczMat ou LiczMat Pro) retenu à la connexion. Les calculateurs ne chargent pas Firebase et doivent quand même savoir s'il faut te proposer un compte. Il ne contient aucune adresse e-mail ni rien d'autre sur toi.",
