    guide_calcs_back: "Guides qui utilisent ce calculateur",
    g_klej_t: "Combien de colle à carrelage",
    g_klej_d: "La consommation de colle suit le peigne, et le peigne suit le format du carreau. Ensuite le joint, et le carrelage lui-même avec une marge pour les coupes.",
    g_klej_s1: "Choisis le peigne selon le format. Petite faïence : 6 mm. Grès 60×60 : 8–10 mm. Grand format : 12 mm et double encollage.",
    g_klej_s2: "Multiplie la surface par la consommation du sac et divise par le poids du sac. Les valeurs courantes sont 4 kg/m² avec un peigne de 6 mm et 5 kg/m² avec celui de 10 mm.",
    g_klej_s3: "Calcule le joint à part : il dépend du format du carreau, de son épaisseur et de la largeur du joint. Compte le carrelage avec une marge pour les coupes.",
    g_klej_tip: "La consommation sur le sac suppose un support plan. Un mur voilé boit bien plus de colle que ne le dit l'étiquette. Au-delà d'environ 5 mm d'écart, ragréé d'abord : la colle coûte plus cher que le ragréage.",
    g_gladz_t: "Combien d'enduit de lissage pour un mur",
    g_gladz_d: "L'enduit de lissage se compte en kilogrammes par mètre carré et par millimètre de couche. Deux couches fines plutôt qu'une épaisse.",
    g_gladz_s1: "Calcule la surface des murs et du plafond et retire les fenêtres et les portes. Cette surface est le point de départ de chaque couche.",
    g_gladz_s2: "Prends la consommation du sac : enduit au plâtre environ 1 kg/m² par millimètre, polymère environ 1,2 kg/m². Multiplie par l'épaisseur de la couche.",
    g_gladz_s3: "Multiplie par le nombre de couches et divise par le poids du sac. Arrondis au supérieur : un demi-sac ne s'achète pas.",
    g_gladz_tip: "Sur un enduit brut, la première couche passe plus épaisse : elle comble les irrégularités. Compte-la à 1,5 mm et la seconde à 0,5 mm. Applique d'abord un primaire.",
    g_ocieplenie_t: "Isoler une maison avec du polystyrène",
    g_ocieplenie_d: "Un système ITE, ce n'est pas que le polystyrène : c'est la colle, les chevilles, le treillis, la couche de renfort et l'enduit. Tous sortent de la même surface.",
    g_ocieplenie_s1: "Calcule la surface de façade : le périmètre du bâtiment fois sa hauteur, moins les fenêtres et les portes. Compte les tableaux à part si tu les isoles aussi.",
    g_ocieplenie_s2: "Choisis l'épaisseur du polystyrène et compte les paquets. Puis les chevilles : en général 6 au m², davantage aux angles et au-dessus de 8 m. Compte la colle deux fois, une pour le collage et une pour la couche de renfort.",
    g_ocieplenie_s3: "Prévois environ 10 % de treillis en plus pour les recouvrements et prends l'enduit mince à sa propre consommation au m².",
    g_ocieplenie_tip: "Le nombre de chevilles ne vaut pas pour toute la maison. Aux angles elles sont plus serrées, et au-dessus de 8 m la zone de vent change. Vois l'étude avant de commander.",
    g_rozkroj_t: "Découper un panneau avec moins de chutes",
    g_rozkroj_d: "Combien de panneaux acheter pour une liste de pièces et comment les disposer pour que la chute soit la plus petite possible. La scie prend aussi de la matière.",
    g_rozkroj_s1: "Liste les pièces : largeur, longueur et quantité. Ajoute une marge pour le chant si le chant se pose après la découpe.",
    g_rozkroj_s2: "Indique le format du panneau et le trait de scie. Une scie à panneaux prend environ 3–4 mm à chaque coupe ; sur quelques dizaines de coupes, ce sont des centimètres entiers.",
    g_rozkroj_s3: "Décide si les pièces peuvent pivoter. Un panneau avec un fil ou un motif ne le peut pas, et la chute augmente : calcule les deux cas et compare.",
    g_rozkroj_tip: "Le résultat est un plan de coupe, pas une commande. Avant de commander, vérifie que chaque pièce entre dans le sens où l'algorithme l'a tournée. Avec un fil, tourner une pièce change l'aspect de la façade même si la cote est bonne.",
    nav_app_page: "L'application",
    apppage_title: "LiczMat pour Android",
    apppage_lead: "Les mêmes calculs que sur le site, dans la poche et hors réseau. Calculateurs, catalogue de matériaux, pièces, projets, devis en PDF, convertisseur d'unités et carte des négoces.",
    apppage_meta: "LiczMat pour Android : calculateur gratuit de matériaux. Catalogue, pièces, projets, devis en PDF et carte des magasins. Calcule hors ligne.",
